-- Owner-requested public notes. Data only: no schema/settings changes.
-- The normal migration runner wraps this in a transaction and records its checksum.
-- Serialize this short seed against concurrent CMS writes, including slug edits.
LOCK TABLE entries IN SHARE ROW EXCLUSIVE MODE;
WITH notes(id, payload) AS (
  VALUES
    ('ad3969e1-3a85-5b64-918c-704ce57dffc7', $note${"title": "ASP.NET Core DI：同一個介面，多個實作到底怎麼注入？", "slug": "aspnet-core-di-multiple-implementations", "excerpt": "從單一注入、IEnumerable 到 enum resolver，釐清註冊順序、生命週期與選擇實作的責任。", "body": "同一個介面可以有多個實作。但「容器能建立哪些服務」和「這次業務應該使用哪一個」，是兩個不同的問題。這篇用小範例整理這個容易混淆的邊界；範例不連接真實設備或資料庫。\n\n## 先看註冊，再看要求的型別\n\n在 ASP.NET Core 專案中，以下註冊並不會把第一個實作從集合移除：\n\n```csharp\nbuilder.Services.AddScoped<IReportExporter, CsvReportExporter>();\nbuilder.Services.AddScoped<IReportExporter, JsonReportExporter>();\n```\n\n要求單一 `IReportExporter` 時，內建容器會選擇最後註冊的實作；要求 `IEnumerable<IReportExporter>` 時，會取得所有註冊，順序與註冊順序相同。[Microsoft 的註冊文件](https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection/service-registration)明確區分這兩種解析方式。\n\n這代表「後面覆蓋前面」只適合描述單一服務的解析結果，不適合拿來理解整個服務集合。\n\n## 選擇規則需要明確表達\n\n假設使用者可以選 CSV 或 JSON，Controller 不應靠改變 DI 註冊順序決定本次輸出格式。可以讓每個實作宣告自己的格式，再在很小的 resolver 中集中選擇與錯誤檢查。\n\n下面是介面與選擇器的示意程式；實際輸出檔案的方法應依專案需求另外實作。\n\n```csharp\npublic enum ExportFormat { Csv, Json }\n\npublic interface IReportExporter\n{\n    ExportFormat Format { get; }\n}\n\npublic sealed class ReportExporterResolver\n{\n    private readonly IReadOnlyDictionary<ExportFormat, IReportExporter> _exporters;\n\n    public ReportExporterResolver(IEnumerable<IReportExporter> exporters)\n    {\n        ArgumentNullException.ThrowIfNull(exporters);\n        var map = new Dictionary<ExportFormat, IReportExporter>();\n        foreach (var exporter in exporters)\n        {\n            if (!map.TryAdd(exporter.Format, exporter))\n                throw new InvalidOperationException($\"Duplicate export format: {exporter.Format}\");\n        }\n        _exporters = map;\n    }\n\n    public IReportExporter Resolve(ExportFormat format) =>\n        _exporters.TryGetValue(format, out var exporter)\n            ? exporter\n            : throw new ArgumentOutOfRangeException(nameof(format), format, \"Unsupported format.\");\n}\n```\n\n這不是要求每個服務都加一層 Factory。只有一個實作、沒有執行期選擇需求時，直接注入介面通常更容易閱讀。只有兩個固定分支時，一個清楚的選擇方法也可能足夠。\n\n## 生命週期比類別名稱更重要\n\n這個例子中的 exporters 是 scoped，resolver 也應以 scoped 註冊，避免 singleton 長期持有 scoped 服務。Dictionary 不再修改，只代表選擇表沒有後續寫入，**不代表每個 exporter 本身就是 thread-safe**。共享狀態、檔案寫入、資料庫連線仍要分別檢查。[DI 指南](https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection-guidelines)說明了這些生命週期與並發限制。\n\n支援 keyed services 的專案也可以使用內建 keyed registration，key 不必是 magic string，可以是 enum。這是可行替代方案，不是為了套模式而一定要替換現有程式。[Keyed services 說明](https://learn.microsoft.com/en-us/dotnet/core/extensions/dependency-injection/overview#keyed-services)可用來對照選擇。\n\n## 值得保留的測試\n\n至少測試已支援格式、未知 enum 值，以及重複格式註冊。另用一個整合測試確認服務能在正確 scope 中解析。我的設計取捨是：先讓選擇規則可見，再決定是否值得引入更多抽象；不要讓容器註冊順序偷偷成為業務規則。\n", "cover": "", "coverAlt": "", "category": "Backend Engineering", "tags": ["C#", "ASP.NET Core", "DI"], "featured": false, "seoTitle": "", "seoDescription": "", "demoUrl": "", "repoUrl": ""}$note$::jsonb),
    ('58e01153-2449-5ca8-9e4d-72a4bee6138e', $note${"title": "檔案同步遇到 TLS 憑證名稱不符：先檢查 URL", "slug": "tls-name-mismatch-file-sync", "excerpt": "把 DNS、重新導向、TLS 與 API 驗證拆開排查；恢復連線後，還要驗證同步狀態與補傳結果。", "body": "同步程式原本可以連線，伺服器改用 HTTPS 後卻開始失敗。看到 `RemoteCertificateNameMismatch`，先別急著停用憑證驗證：這個錯誤是在提醒我們「連線對象的名稱」與「憑證證明的身分」不一致。\n\n以下使用示意網域，不包含實際系統位置或存取金鑰。\n\n## DNS 正確，不代表憑證名稱正確\n\n`sync.example.com` 和某個舊主機名稱即使都指向同一台伺服器，也不代表兩個名稱都被憑證涵蓋。名稱驗證的重點是客戶端使用的服務身分，而不是兩個名稱最後有沒有解析成同一個 IP。[RFC 9525](https://www.rfc-editor.org/rfc/rfc9525.html)定義了 TLS 服務身分的驗證原則。\n\n.NET 也把名稱不符、憑證鏈錯誤、沒有收到憑證分成不同的 `SslPolicyErrors`。因此，名稱不符不應直接被當成「憑證過期」處理。[SslPolicyErrors 文件](https://learn.microsoft.com/en-us/dotnet/api/system.net.security.sslpolicyerrors)可用來對照實際錯誤。\n\n## 沿著真正的請求路徑檢查\n\n先看客戶端設定的 URL，再看 HTTP 回應是否導向另一個 HTTPS URL，最後確認目標名稱與伺服器實際提供的憑證。IIS 上若有多個 HTTPS binding，也要確認主機名稱與憑證綁定，而不是只檢查「已經裝了憑證」。\n\n在 Windows PowerShell 中，可以用以下唯讀指令查看 DNS 與回應；請把示意網域換成要排查的服務。\n\n```powershell\nResolve-DnsName sync.example.com\ncurl.exe -I --max-time 15 http://sync.example.com/\ncurl.exe -v --max-time 15 https://sync.example.com/\n```\n\n第一個 HTTP 測試刻意沒有自動跟隨重新導向，方便看清楚 `Location`。不要把帶有 Authorization、Cookie、金鑰參數或內部路徑的完整輸出貼到公開平台。[curl 官方手冊](https://curl.se/docs/manpage.html)說明了 `-I`、`-v` 與重新導向選項。\n\n## 修正設定，不要取消身分驗證\n\n比較穩妥的修正通常是讓客戶端直接使用正確的 HTTPS 服務名稱，或修正伺服器提供的憑證及 binding。具體要改哪一邊，取決於實際的 URL、憑證 SAN 與部署設定。\n\n不要在正式程式加入永遠回傳成功的憑證驗證 callback，也不要把 `curl -k` 的成功當成正式驗收。那只會繞過原本需要驗證的安全條件。[Microsoft 的 CA5359 說明](https://learn.microsoft.com/en-us/dotnet/fundamentals/code-analysis/quality-rules/ca5359)也提醒，不應停用憑證驗證。\n\n## 連得上之後，才輪到同步正確性\n\nTLS 修好，不等於漏掉的檔案已經補齊。我的檢查順序會是：確認 API 驗證成功、確認 client 的狀態檔可以反序列化、比對 server 端檔案或校驗值，再用一個小檔案驗證新建與修改。\n\n若接著出現 `LastSyncUtc` 的 JSON 型別不符，就把它當成另一個資料格式問題處理，先備份狀態檔，再核對版本。不要直接刪除狀態檔；不同同步策略對重新掃描、刪除與衝突的處理可能不同，不能只憑「會重算 hash」就保證沒有風險。\n\n真正的完成條件不是 log 不再顯示 SSL error，而是「連線安全，且應同步的資料確實到達」。\n", "cover": "", "coverAlt": "", "category": "System Integration", "tags": ["TLS", "HTTP", "ASP.NET Core"], "featured": false, "seoTitle": "", "seoDescription": "", "demoUrl": "", "repoUrl": ""}$note$::jsonb),
    ('31ebda19-88ea-5fc5-8e8f-e21e7325d141', $note${"title": "A Practical 502 Checklist: Follow the Request, Not the Guess", "slug": "502-follow-the-request", "excerpt": "Separate the running process, container port, gateway target, and deployed revision before changing infrastructure settings.", "body": "A successful build is not proof that a website is reachable. A healthy response inside a container is not proof that the public gateway can reach it either. I use a small evidence table to keep those claims separate.\n\nThis is a general troubleshooting checklist, not a claim that every 502 has the same cause.\n\n## Start at the nearest boundary\n\nCheck the application from inside its container, then repeat the health request from a machine outside the hosting platform. Record the status, response body, port, revision, and time. A health response with a commit identifier helps distinguish a repaired service from an older instance that happens to be healthy.\n\n```text\nBrowser -> HTTPS gateway -> container target port -> application -> database\n```\n\nIf a container answers on 8080 but refuses a connection on 4321, you know which of those two ports is accepting requests. You do not yet know which port the gateway targets. Verify that setting instead of immediately changing both sides.\n\n## EXPOSE and the application listener are different things\n\nA Dockerfile can declare `EXPOSE 4321` while a runtime `PORT=8080` makes an application listen elsewhere. Docker's `EXPOSE` instruction documents an intended port; it does not start a listener or publish a port by itself. Hosting platforms can use that declaration when configuring routing. See the [Dockerfile reference](https://docs.docker.com/reference/dockerfile/#expose) and [Zeabur public networking documentation](https://zeabur.com/docs/en-US/deploy/networking/public-networking).\n\nFor an Astro Node standalone server, inspect `HOST` and `PORT` in the actual running environment, not only in a local configuration file. The [Node adapter documentation](https://docs.astro.build/en/guides/integrations-guide/node/) describes those runtime options. A process listening only on loopback may pass a local probe without being reachable through the container's network interface.\n\n## Read startup logs, not just build progress\n\nA clone progress bar says little about application readiness. Startup may still depend on secrets, file permissions, a database connection, or migrations. Preserve the first useful runtime error and the lines around it before restarting the instance.\n\nUse a narrow question for every check:\n\n| Evidence | What it supports | What it does not prove |\n| --- | --- | --- |\n| Build completed | An artifact was produced | The process started |\n| Local health is 200 | That local endpoint responded | Public routing is correct |\n| Public health is 200 with the expected revision | The public path reached that version | Login and writes work |\n| Login and a controlled workflow succeed | The tested user journey works | Every workflow is correct |\n\nThese distinctions prevent a configuration change from being credited with fixing a problem that was never measured.\n\n## Change one boundary at a time\n\nWhen the gateway target and listener disagree, align them deliberately. When they already match, investigate binding, instance health, and routing rather than repeatedly swapping ports. Do not rotate authentication secrets, delete volumes, or recreate the database merely because a gateway returned 502.\n\nFinally, repeat the external health check and test the page that originally failed. In a stateful application, use a safe, reversible workflow for write verification. A green infrastructure check is an important milestone, not a substitute for application acceptance.\n", "cover": "", "coverAlt": "", "category": "Deployment", "tags": ["Docker", "HTTP", "Troubleshooting"], "featured": false, "seoTitle": "", "seoDescription": "", "demoUrl": "", "repoUrl": ""}$note$::jsonb),
    ('2f176f3d-6f80-54c3-9b95-35d4a7976c83', $note${"title": "MES 跨系統整合：逾時之後，先確認是否已經成功", "slug": "mes-timeouts-idempotency", "excerpt": "以報工與進出站為例，拆開重試、冪等與交易邊界，避免把「沒有收到回應」當成「對方沒有執行」。", "body": "把 MES 接到外部系統，最容易低估的狀態不是明確失敗，而是「結果未知」。客戶端逾時，只能證明自己沒有在期限內取得完整回應，不能直接證明對方沒有寫入資料。\n\n這篇使用假設的報工流程討論設計取捨，不對應任何客戶的資料表或既有業務規則。\n\n## 一個可能發生的時間順序\n\n假設外部服務已經接受報工、完成寫入，但回應在網路上中斷。MES 沒收到成功訊息，立刻把同一筆數量再送一次。如果對方每收到一次就新增一筆，重試反而製造了重複報工。\n\n因此我的第一個問題不是「重試幾次」，而是「這一次和上一次，是不是同一個業務操作？」Microsoft 的 [Retry pattern](https://learn.microsoft.com/en-us/azure/architecture/patterns/retry)也特別提醒這種副作用與交易一致性問題。\n\n## 先定義穩定的操作識別\n\n一個可討論的契約是：每次新的報工作業有獨立的操作 ID；同一次作業的網路重送沿用相同 ID，並包含可驗證的相同請求內容。對方看到重複 ID 時，回傳已完成的結果，而不是再新增一次。\n\n但「用工單加站點當 key」不一定正確：同一工單可能允許多次合法報工。哪些事件應合併、哪些應獨立，必須由實際業務規則決定。還要定義相同 ID 搭配不同內容時應拒絕，不能默默沿用舊結果。\n\n## 先查再寫，本身不是並發保證\n\n兩個執行緒可能同時查到「不存在」，然後各自新增。因此，應核對資料庫或接收端是否有真正的唯一性約束，以及去重紀錄和業務寫入能否原子完成。\n\n若現有 schema 與外部 API 都沒有這種能力，不能僅在程式加一個 `if` 就宣稱做到 exactly-once。也不要把單一程序的記憶體鎖，誤當成跨機器鎖。需要變更契約或 schema 時，應另外提出並評估，不應在小型重構中偷偷加入。\n\n## 本機交易，不會自動涵蓋遠端 HTTP\n\n在 C#／Dapper／SQL Server 專案裡，把幾個 SQL 命令放進同一個 transaction，不代表外部 HTTP 呼叫也會跟著 rollback。外部已完成的操作，可能需要查詢確認或補償流程，而不是把本機例外當成全域回復。\n\n如果本機資料與待送訊息必須一起保存，可以評估 transactional outbox；但它有資料結構、派送器、去重與維運成本，不是每個整合都該直接套用。Microsoft 的 [Transactional Outbox 說明](https://learn.microsoft.com/en-us/azure/architecture/databases/guide/transactional-outbox-cosmos)以特定儲存系統示範這個概念，不能把實作細節直接當成 SQL Server 版本。\n\n## 把未知結果放進 UI\n\n我的建議狀態至少區分「待處理、處理中、已確認成功、可重試失敗、結果待確認」。結果未知時，先提供查詢或人工核對入口，而不是讓使用者不停按相同的送出按鈕。\n\n測試也應涵蓋「對方已寫入但回應中斷」、「同一操作同時送出」、「相同 ID 不同內容」、「重啟後恢復」與「合法的第二次報工」。這比只測成功回應，更接近整合系統真正需要保護的業務行為。\n", "cover": "", "coverAlt": "", "category": "System Integration", "tags": ["MES", "Reliability", "Backend"], "featured": false, "seoTitle": "", "seoDescription": "", "demoUrl": "", "repoUrl": ""}$note$::jsonb),
    ('403914fa-d832-5fc7-821f-bd481ae228f5', $note${"title": "從後端工程師出發：製造業 AI PoC 先做資料與評估", "slug": "manufacturing-ai-poc-evaluation", "excerpt": "先把預測時點、標籤、漏檢成本與上線邊界說清楚，再決定模型和整合方式。", "body": "想把 AI 接到製造現場，很容易先被模型、GPU 或展示畫面吸引。我的學習切入點會更接近後端工程：先定義輸入、輸出、時間點、失敗處理與驗收條件，讓模型成為系統中的一個可替換元件。\n\n這是一份 PoC 規劃筆記，不是已在產線取得成效的案例，也不承諾特定準確率。\n\n## 選一個小而可驗證的問題\n\n例如「在某道製程結束時，預測這一批是否需要額外檢查」。先說清楚模型何時被呼叫、當時拿得到哪些欄位、判定結果由誰記錄，以及結果會觸發什麼動作。\n\n不良標籤若來自後續檢驗，就不能把後續才知道的檢驗數值當成預測輸入。這種資訊外洩可能讓離線成績漂亮，實際上線卻無法使用。資料切分與前處理也應避免讓測試資料影響訓練；[scikit-learn 的資料洩漏說明](https://scikit-learn.org/stable/common_pitfalls.html#data-leakage)提供了清楚的例子。\n\n## 不要只看 Accuracy\n\n假設一千筆測試資料只有十筆不良，全部猜良品仍有 99% accuracy，卻沒有找出任何不良。這是簡單的算術，也是一個提醒：指標要對應風險，不只是追求好看的數字。\n\n可以把「不良」視為 positive，分別檢查：實際不良有多少被找到（recall）、被模型判為不良的項目有多少是真的（precision），以及不同門檻下的漏檢與誤報數。先定義每種錯誤的代價，再選擇判定門檻。[ML.NET 評估指標](https://learn.microsoft.com/en-us/dotnet/machine-learning/resources/metrics)提醒，不平衡資料不能只靠 accuracy 評估。\n\n## 讓驗證接近未來的使用情境\n\n我的 PoC 會先保留一段較新的資料作為最後驗收，並檢查同一批次、同一工件或高度相似的影像是否跨越了訓練與測試集合。具體切分方式仍要配合資料來源：某些問題需要依時間切，某些需要依批次或設備分組。\n\n先建立簡單基準，例如固定規則或現有檢驗策略，再看模型是否真正增加價值。否則只能知道模型有分數，不知道它是否比現在的方法更好。\n\n## ASP.NET Core 可以先守住整合邊界\n\nPoC 階段可以讓 API 驗證輸入、記錄模型版本、控制逾時與回傳明確狀態。模型服務不可用、必要欄位缺少或信心不足時，應回傳「無法判定」，不要直接當成良品通過。\n\n建議先以 shadow mode 記錄推論，與實際檢驗結果比對，不立即接管產線決策。這是本篇的部署取捨，不是所有工廠都必須採用的固定流程。涉及安全或關鍵品質放行時，還需要現場專家的風險評估。\n\n## 第一份驗收報告應該留下什麼\n\n我會記錄問題定義、資料期間、樣本與不良數、欄位可用時點、切分方法、基準策略、錯誤案例、模型版本，以及 API 延遲和失敗處理。上線後再追蹤輸入分布、人工複核與實際結果，而不是只保留一個離線分數。\n\n對後端工程師來說，這些工作並不是模型以外的雜事。它們正是把一個模型展示，變成可驗證、可維護系統的必要邊界。\n", "cover": "", "coverAlt": "", "category": "AI Learning", "tags": ["AI", "Manufacturing", "Evaluation"], "featured": false, "seoTitle": "", "seoDescription": "", "demoUrl": "", "repoUrl": ""}$note$::jsonb)
), inserted AS (
  INSERT INTO entries (id, kind, content, published, published_at, updated_at, version)
  SELECT notes.id, 'article', notes.payload, notes.payload, now(), now(), 1
  FROM notes
  WHERE NOT EXISTS (
    SELECT 1 FROM entries existing
    WHERE existing.id = notes.id
      OR (existing.kind = 'article' AND (
        existing.content ->> 'slug' = notes.payload ->> 'slug'
        OR existing.published ->> 'slug' = notes.payload ->> 'slug'
      ))
  )
  ON CONFLICT DO NOTHING
  RETURNING content
), labels(kind, name) AS (
  SELECT 'category', content ->> 'category' FROM inserted
  UNION
  SELECT 'tag', jsonb_array_elements_text(content -> 'tags') FROM inserted
)
INSERT INTO taxonomies (id, kind, name, slug)
SELECT md5('kaiyolab-note-taxonomy:' || kind || ':' || name), kind, name,
       'note-' || md5(kind || ':' || name)
FROM labels
WHERE name <> ''
ON CONFLICT DO NOTHING;
